    api.removeUiDialog(popup);
    popup=dialog(v.title,`<article class="cps-data-reader">${documentHeading(v.title,`${v.kind||'data'} / ARCHIVE`,displayText(v.description))}${rows.length?`<dl>${rows.map(([k,val])=>`<div><dt>${E(k)}</dt><dd>${E(displayText(val))}</dd></div>`).join('')}</dl>`:''}${v.content?`<section class="cps-rpg-detail">${E(v.content)}</section>`:''}${(v.sections||[]).map(x=>`<section><h4>${E(x.heading)}</h4><div class="cps-rpg-detail">${E(x.body)}</div></section>`).join('')}${!v.content&&!v.sections?.length&&!rows.length?note(tr('Only the supplied summary is available. Full file contents have not been received.','มีเพียงบทสรุปที่ส่งมา ยังไม่ได้รับเนื้อหาไฟล์ฉบับเต็ม')):''}</article>`,'cps-data-window');
    decorateDocument(popup,'DATA / ARCHIVE');
