  function iconLibrary(){
    const owner=api.chatBucket(),G=globalThis.CyberpunkItemGuide,d=dialog(tr('Item icon library','คลังภาพไอเทม'),`${note(tr('Import only artwork you own or have permission to use. No game images are bundled and no external URLs are loaded. Packs match exact catalog IDs, never fuzzy names.','นำเข้าเฉพาะภาพที่เป็นเจ้าของหรือได้รับอนุญาต ไม่มีภาพเกมแนบมาและไม่โหลด URL ภายนอก ชุดภาพจับคู่รหัสไอเทมตรงตัว ไม่เดาชื่อ'))}<pre class="cps-rpg-detail">${E(JSON.stringify({version:1,entries:[{key:'cps:sandevistan-apogee',image:'data:image/png;base64,...',credit:'Creator / permission'}]},null,2))}</pre>${note(tr('Per pack: up to 200 images / 8 MB JSON. Per chat: 500 mappings / 20 MB maximum. Each raster data URI must be under 500 KB. Import adds or replaces only the matching keys.','ต่อชุด: สูงสุด 200 ภาพ / JSON 8 MB ต่อแชต: 500 รหัส / 20 MB แต่ละ data URI ภาพต้องต่ำกว่า 500 KB นำเข้าจะเพิ่มหรือแทนเฉพาะรหัสที่ตรงกัน'))}<input type="file" accept="application/json,.json" data-icon-pack><p data-icon-status role="status"></p><div data-icon-entries></div>`);
    const draw=()=>{d.querySelector('[data-icon-entries]').innerHTML=(state().itemIcons||[]).map(x=>`<p><code>${E(x.key)}</code> · ${E(x.credit)} <button type="button" class="cps-button" data-delete-icon="${E(x.key)}">${E(tr('Remove mapping','นำการจับคู่ออก'))}</button></p>`).join('');d.querySelectorAll('[data-delete-icon]').forEach(b=>b.onclick=()=>{if(owner!==api.chatBucket()||!d.isConnected)return;state().itemIcons=state().itemIcons.filter(x=>x.key!==b.dataset.deleteIcon);event('icon mapping removed',b.dataset.deleteIcon);draw();render();});};draw();
    d.querySelector('[data-icon-pack]').onchange=async e=>{const status=d.querySelector('[data-icon-status]'),file=e.target.files?.[0];if(!file)return;try{if(file.size>8e6)throw Error('Icon pack exceeds 8 MB');const entries=G.validateIconPack(JSON.parse(await file.text()));if(owner!==api.chatBucket()||!d.isConnected)return;const merged=new Map((state().itemIcons||[]).map(x=>[x.key,x]));entries.forEach(x=>merged.set(x.key,x));const next=[...merged.values()];if(next.length>500||JSON.stringify(next).length>20e6)throw Error('Chat icon library exceeds 500 entries / 20 MB');state().itemIcons=next;event('icon pack',`${entries.length} mappings imported`);status.textContent=tr('Imported. Matching items use these images.','นำเข้าแล้ว ไอเทมที่ตรงรหัสจะใช้ภาพเหล่านี้');draw();render();}catch(err){status.textContent=err.message;}};
  }
  const sections=[['status','Status','สถานะ','consumable'],['cyberware','Cyberware','ไซเบอร์แวร์','cyberware'],['weapons','Weapons','อาวุธ','weapons'],['balance','Balance','บัญชี','component'],['inventory','Inventory','คลังอุปกรณ์','item'],['mail','Mailbox','กล่องจดหมาย','data'],['quickhacks','Quickhack Deck','เด็ค Quickhack','quickhack'],['skills','Skills / Hacking','ทักษะ / แฮ็ก','quickhack'],['quests','Missions / Quests','ภารกิจ','data'],['map','Night City','แผนที่','mod'],['relic','Relic / Blackwall','Relic / Blackwall','cyberware'],['property','House / Property','บ้าน / ทรัพย์สิน','mod'],['vehicles','Garage','โรงรถ','mod'],['ai','AI / Blackwall','AI / Blackwall','quickhack'],['support','System / Recovery','ระบบ / กู้คืน','data'],['settings','Settings','ตั้งค่า','mod']];
  const sectionTitle=key=>{const s=sections.find(x=>x[0]===key);return s?tr(s[1],s[2]):key;};
  function meter(label,value,maximum,kind='') {
    const max=Math.max(1,Number(maximum)||1),v=Math.max(0,Number(value)||0),percent=C.cap(v/max*100,0,100);
    kind=kind||({'HEALTH':'health','STAMINA':'stamina','RAM':'ram','CYBERWARE':'capacity','STRESS':'stress','RELIC POINTS':'relic','BLACKWALL EXPOSURE':'blackwall'}[label]||'capacity');
    const count=kind==='ram'?Math.min(24,Math.ceil(max)):kind==='relic'?10:20;
    return `<div class="cps-rpg-meter cps-hud-meter ${kind} ${v>max?'overload':''}" data-vital="${kind}"><div class="cps-hud-meter-head"><span>${E(label)}</span><div><b>${Math.round(v)}</b><small>/ ${Math.round(max)}</small></div></div><div class="cps-hud-track" role="progressbar" aria-label="${E(label)}" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${Math.min(v,max)}" aria-valuetext="${Math.round(v)} / ${max}${v>max?' · over capacity':''}" style="--hud-level:${percent}%;--hud-segments:${count}"><div class="cps-hud-fill"></div><div class="cps-hud-divisions" aria-hidden="true"></div></div><div class="cps-hud-meter-foot"><span>${kind==='ram'?tr('MEMORY UNITS','หน่วยความจำ'):kind==='health'?tr('VITAL SIGNS','สัญญาณชีพ'):v>max?tr('OVER CAPACITY','เกินขีดจำกัด'):tr('NEURAL TELEMETRY','การตรวจวัดประสาท')}</span><span>${Math.round(v/max*100)}%</span></div></div>`;
  }
  function heading(kicker,title,meta=''){return `<header class="cps-section-heading"><div><small>${E(kicker)}</small><h3>${E(title)}</h3></div>${meta?`<span class="cps-section-count">${E(meta)}</span>`:''}</header>`;}
  function bodyDiagram(a){
    const linked=a.inventory.filter(it=>it.equipped&&it.category==='cyberware');
    const outline='M120 22C108 22 101 30 102 44L104 60Q109 74 116 76V86Q104 89 91 93C78 94 72 103 69 116L61 153 54 180 46 216 43 230 44 247Q47 252 49 246L50 233 52 249Q55 253 56 248L57 232 59 244Q62 247 63 242L64 228 68 220Q70 216 67 211L64 207 76 177 85 148 88 134 93 151 96 179 93 203Q85 225 88 247L92 288 94 307 93 329 96 367 95 384 87 394Q84 400 91 402H111Q116 400 113 390L112 376 116 340 116 313 119 283 120 256';
    const muscles='M115 96Q104 96 91 104L92 125Q103 137 117 128M94 143Q104 151 117 145M99 163L115 165M99 179L115 181M99 195L115 197M94 213Q108 211 118 225M96 239Q111 246 111 270L105 294M102 319Q100 341 105 361M79 113Q72 127 70 150M69 165L59 199M113 37Q108 39 108 44M108 53L115 53M112 64L118 66';
    return `<div class="cps-body-scan cps-anatomy"><div class="cps-scan-caption"><span>BIOMETRIC / LINK</span><b>${String(linked.length).padStart(2,'0')} ${E(tr('INSTALLED','ติดตั้ง'))}</b></div><svg viewBox="0 0 240 420" role="img" aria-label="${E(tr('Human anatomy with installed cyberware regions','แผนผังร่างกายและตำแหน่งไซเบอร์แวร์'))}"><g class="cps-anatomy-guides" fill="none" stroke="currentColor" stroke-width=".5"><path d="M20 20h30M20 20v30M220 20h-30M220 20v30M20 400h30M20 400v-30M220 400h-30M220 400v-30M120 12v396"/><ellipse cx="120" cy="410" rx="52" ry="4"/>${[85,155,225,305].map(y=>`<path d="M30 ${y}h180"/>`).join('')}</g><g class="cps-human-shell" stroke="currentColor" stroke-width="1.2"><path d="${outline}Z"/><path d="${outline}Z" transform="translate(240 0) scale(-1 1)"/></g><g class="cps-human-detail" fill="none" stroke="currentColor" stroke-width=".8"><path d="${muscles}"/><path d="${muscles}" transform="translate(240 0) scale(-1 1)"/><path d="M116 78h8M113 84h14M109 89h22M117 136h6v70h-6zM111 232l9 9 9-9M101 303h8M131 303h8M117 58l3 3 3-3M115 69h10"/></g><path class="cps-anatomy-neural" fill="none" d="M120 82v153M120 97l-28 12-16 58-16 45M120 97l28 12 16 58 16 45M120 235l-14 71 1 73M120 235l14 71-1 73"/>${C.implantGroups.map((g,i)=>{const active=linked.some(it=>C.implantSlot(it.slot)===g.id),left=i%2===0,x2=left?28:212;return `<g class="cps-anatomy-region ${active?'linked':''}"><title>${E(tr(g.en,g.th))}: ${linked.filter(it=>C.implantSlot(it.slot)===g.id).length}</title><path d="M${g.x} ${g.y}L${left?79:161} ${g.y+(i%3-1)*8}H${x2}"/><circle cx="${g.x}" cy="${g.y}" r="${active?4:2.5}"/><text x="${left?15:215}" y="${g.y+(i%3-1)*8+2}">${String(i+1).padStart(2,'0')}</text></g>`;}).join('')}</svg><div class="cps-scan-caption"><span>${E(tr('CAPACITY','ขีดจำกัด'))}</span><b>${C.load(a)} / ${a.capacity}</b></div></div>`;
  }
  function implantSlots(a){
    const all=a.inventory.filter(it=>it.category==='cyberware'&&it.equipped);
    const groups=[...C.implantGroups,...[...new Set(all.map(it=>C.implantSlot(it.slot)))].filter(slot=>!C.implantGroups.some(g=>g.id===slot)).map(id=>({id,en:id||'Unassigned',th:id||'ไม่ระบุตำแหน่ง'}))];
    return `<div class="cps-implant-slots">${groups.map((g,i)=>{const installed=all.filter(it=>C.implantSlot(it.slot)===g.id),limit=C.slotLimit(a,g.id);return `<section class="cps-implant-group ${installed.length?'linked':''}"><header><span>${String(i+1).padStart(2,'0')}</span><h4>${E(tr(g.en,g.th))}</h4><b>${installed.length}/${limit}</b></header><div class="cps-implant-sockets">${Array.from({length:Math.max(limit,installed.length)},(_,j)=>{const it=installed[j];return `<button type="button" class="cps-implant-socket ${it?'linked':''}" data-rpg="${E(it?`edit-item:${it.id}`:`slot:${g.id}`)}"><span aria-hidden="true">${it?'◆':'+'}</span><strong>${E(it?.name||tr('Empty socket','ช่องว่าง'))}</strong></button>`;}).join('')}</div>${installed.length>limit?note(tr('Legacy loadout exceeds socket count; unequip before adding.','อุปกรณ์เดิมเกินจำนวนช่อง ถอดบางชิ้นก่อนเพิ่ม')):''}</section>`;}).join('')}</div><details class="cps-rpg-advanced"><summary>${E(tr('Additional implant sockets','ช่องฝังเพิ่มเติม'))}</summary>${note(tr('Story unlocks: License to Chrome adds one Skeleton socket; Ambidextrous adds one Hands socket.','ปลดล็อกตามเนื้อเรื่อง: License to Chrome เพิ่มโครงกระดูก 1 ช่อง และ Ambidextrous เพิ่มมือ 1 ช่อง'))}${buttons(`${a.implantUnlocks?.skeleton?'✓':'+'} License to Chrome`,'socket-unlock:skeleton')}${buttons(`${a.implantUnlocks?.hands?'✓':'+'} Ambidextrous`,'socket-unlock:hands')}</details>`;
  }
  function statusMarkup(a,s){const name=actorName==='user'?state().player.profile?.name||api.context()?.name1||'V':actorName;const risk=C.medical.assess(a,s.turn,s.settings.riskScale).effective;return `${heading('BIOMONITOR / PERSONAL LINK',name,a.cyberpsychosis?'NEURAL INSTABILITY':'CONNECTED')}${a.profile?`<section class="cps-campaign-review"><strong>${E(a.profile.lifepath==='Other / กำหนดเอง'?a.profile.customPath:a.profile.lifepath)}</strong><p>${E([a.profile.age,a.profile.gender,a.profile.occupation].filter(Boolean).join(' / '))}</p><details><summary>${E(tr('Biography','ประวัติตัวละคร'))}</summary><p>${E(a.profile.background)}</p></details></section>`:''}${progressionMarkup(a)}<div class="cps-status-overview"><div class="cps-status-vitals">${meter('HEALTH',a.hp,a.maxHp)}<div class="cps-vital-pair">${meter('STAMINA',a.stamina,a.maxStamina)}${meter('RAM',a.ram,a.maxRam)}</div>${meter('CYBERWARE',C.load(a),a.capacity)}${buttons(tr('Manage Capacity / sources','แก้ Capacity / ดูที่มา'),'manage-capacity')}</div>${bodyDiagram(a)}</div><div class="cps-neural-assessment"><div><small>${E(tr('NEURAL STRAIN','ภาระระบบประสาท'))}</small><strong>${risk.toFixed(0)}<span>%</span></strong><p>${E(tr('Effective neural load / open Medical Link','ภาระหลังหักฤทธิ์ยา / เปิด Medical Link'))}</p></div>${meter('STRESS',a.stress,100)}</div><div class="cps-rpg-actions">${buttons(tr('Recover','พักฟื้น'),'recover')}${buttons(tr('Activity & notifications','กิจกรรมและแจ้งเตือน'),'notices')}</div><details class="cps-rpg-advanced"><summary>${E(tr('Starting values & scenario setup','ค่าตั้งต้นและการตั้งสถานการณ์'))}</summary>${note(tr('Recovery spends one turn. Risk uses adjustable role-play rules.','พักฟื้นใช้หนึ่งเทิร์น ความเสี่ยงใช้กติกาโรลเพลย์ที่ปรับได้'))}${buttons(tr('Edit starting status','แก้ไขสถานะตั้งต้น'),'setup')}</details>`;}
  function itemMarkup(it,s){const canEquip=['cyberware','weapons','clothing','quickhack'].includes(it.category);const cooling=Number(it.cooldownUntil)>s.turn;const canUse=!cooling&&(it.category==='consumable'||it.equipped);const primary=it.shardId?buttons(tr('Read shard','อ่านชาร์ด'),`open-shard:${it.shardId}`):it.category==='quickhack'?buttons(tr('Open deck','เปิดเด็ค'),'tab:quickhacks'):buttons(cooling?tr('Recharging','กำลังฟื้น'):tr('Activate','ใช้งาน'),`use:${it.id}`,canUse?'':'disabled');return `<article class="cps-rpg-item cps-gear-card ${it.equipped?'linked':''}"><div class="cps-gear-topline"><span>${E(it.category.toUpperCase())}</span><b>${it.equipped?'● LINKED':tr('STORED','จัดเก็บ')}</b></div><div class="cps-gear-visual"><span class="cps-gear-blueprint-label">${E(tr('EQUIPMENT SCAN','สแกนอุปกรณ์'))}</span>${itemImage(it)}<span class="cps-gear-quantity">×${it.quantity}</span></div><div class="cps-gear-copy"><h3>${E(it.name)}</h3>${note(globalThis.CyberpunkItemGuide?.describe(it,api.settings().language).summary||it.effect)}<div class="cps-gear-specs">${it.category==='cyberware'?`<span>${E(tr('Capacity','ภาระติดตั้ง'))}<b>${it.capacity}</b></span><span>${E(tr('Slot','ตำแหน่ง'))}<b>${E(it.slot||'—')}</b></span>`:`<span>${E(tr('Cooldown','คูลดาวน์'))}<b>${it.cooldown} ${E(tr('turns','เทิร์น'))}</b></span>`}</div><div class="cps-rpg-actions">${canEquip?buttons(it.category==='quickhack'?(it.equipped?tr('Unload from deck','นำออกจากเด็ค'):tr('Load into deck','ใส่ในเด็ค')):(it.equipped?tr('Unequip','ถอดออก'):tr('Equip','ติดตั้ง')),`equip:${it.id}`):''}${primary}${buttons(tr('Inspect / compare','รายละเอียด / เปรียบเทียบ'),`item-info:${it.id}`)}</div><details class="cps-gear-more"><summary>${E(tr('Details & manage','รายละเอียดและจัดการ'))}</summary><div class="cps-rpg-actions">${buttons(tr('Edit','แก้ไข'),`edit-item:${it.id}`)}${buttons(tr('Share','ส่งข้อมูล'),`share-item:${it.id}`)}${buttons(tr('Remove one','นำออกหนึ่งชิ้น'),`remove-item:${it.id}`)}</div></details></div></article>`;}
  function skillMarkup(sk,s){const remaining=Math.max(0,sk.readyTurn-s.turn);return `<article class="cps-rpg-skill cps-ability-card"><div class="cps-ability-heading">${icon('quickhack')}<div><small>QUICK ACCESS / LV.${sk.level}</small><h3>${E(sk.name)}</h3></div><span class="cps-state-pill ${remaining?'waiting':''}">${remaining?`${remaining} ${tr('turns','เทิร์น')}`:tr('READY','พร้อม')}</span></div>${note(sk.description)}${meter('MASTERY',sk.xp,100,'mastery')}<div class="cps-ability-footer"><span><b>${sk.cost}</b> ${E(sk.resource.toUpperCase())}<small>${sk.cooldown} ${E(tr('turn cooldown','เทิร์นคูลดาวน์'))}</small></span>${buttons(tr('Activate','ใช้งาน'),`skill:${sk.id}`,remaining?'disabled':'')}</div></article>`;}
  function relicMarkup(a){return `${heading('RESTRICTED NEURAL PARTITIONS','Relic / Blackwall')}<div class="cps-partition-grid"><section class="cps-neural-partition relic"><div class="cps-partition-header">${icon('cyberware')}<div><small>RELIC INTERFACE</small><h3>${a.relic.unlocked?'LINK ESTABLISHED':'LOCKED'}</h3></div></div>${meter('RELIC POINTS',a.relic.points,Math.max(10,a.relic.points))}<div class="cps-relic-tree">${['Jailbreak','Emergency Cloaking','Vulnerability Analytics'].map((name,i)=>buttons(`${String(i+1).padStart(2,'0')} / ${name}${a.relic.abilities.includes(name)?' ✓':' · 1 RP'}`,`relic:${name}`,`${!a.relic.unlocked||a.relic.abilities.includes(name)?'disabled':''}`)).join('')}</div><details class="cps-rpg-advanced"><summary>${E(tr('Scenario unlocks','ปลดล็อกตามสถานการณ์'))}</summary>${buttons(a.relic.unlocked?tr('Relic linked','Relic เชื่อมต่อแล้ว'):tr('Unlock Relic','ปลดล็อก Relic'),'unlock-relic')}${buttons(tr('Award 1 point','เพิ่ม 1 แต้ม'),'relic-point')}</details></section><section class="cps-neural-partition blackwall"><div class="cps-partition-header">${icon('quickhack')}<div><small>BLACKWALL / RESTRICTED</small><h3>${a.blackwall.unlocked?'ACCESS AUTHORIZED':'LOCKED'}</h3></div></div>${meter('BLACKWALL EXPOSURE',a.blackwall.exposure,100)}${note(tr('4 RAM per interface. Exposure increases by 20; high exposure causes neural feedback.','ใช้ 4 RAM ต่อการเชื่อมต่อ เพิ่มการสัมผัส 20 ระดับสูงทำให้เกิดผลสะท้อนทางประสาท'))}<div class="cps-rpg-actions">${buttons(tr('Interface','เชื่อมต่อ'),'blackwall',!a.blackwall.unlocked||a.ram<4?'disabled':'')}${buttons(tr('Disconnect / recover','ตัดการเชื่อมต่อ / ฟื้นฟู'),'disconnect')}</div><details class="cps-rpg-advanced"><summary>${E(tr('Scenario unlocks','ปลดล็อกตามสถานการณ์'))}</summary>${buttons(a.blackwall.unlocked?'Blackwall linked':'Unlock Blackwall','unlock-blackwall')}</details></section></div>`;}
function open(name='user',nextTab='status',returnRoute=null){if(nextTab==='campaign'){campaign?.openVault();return;}if(nextTab==='support'){support.open();return;}if(nextTab==='mail'){mail.open();return;}guard(()=>actor(name));if(name!=='user'&&!api.findEffectiveNpc(C.handle(name)))return;const previous=panel?.isConnected?{name:actorName,tab,back:panel.cpsBack}:null;actorName=name;tab=nextTab;closePanel();panel=dialog(name==='user'?'Cyberware':`${name} / Cyberware`,'','cps-rpg-main');panel.cpsBack=returnRoute||(previous?()=>open(previous.name,previous.tab,previous.back):null);panel.querySelector('[data-rpg="close"]').onclick=closePanel;panel.addEventListener('cancel',closePanel);render();}
  function render(){
    if(!panel?.isConnected)return;const a=actor(actorName),s=state();const body=panel.querySelector('.cps-rpg-content');const oldArea=body.querySelector('.cps-rpg-body');const sameTab=panel.dataset.currentTab===tab;const scroll=sameTab?oldArea?.scrollTop||0:0;
    const drafts=sameTab?[...body.querySelectorAll('[data-rpg-settings] input')].map(el=>({name:el.name,value:el.value,checked:el.checked})):[];const focused=body.contains(document.activeElement)?document.activeElement.name:'';
    mapCleanup?.();mapCleanup=null;panel.dataset.currentTab=tab;body.innerHTML=`<div class="cps-rpg-workspace"><nav class="cps-rpg-tabs" aria-label="Cyberware sections">${sections.map(([k,en,th,ic],i)=>`<button type="button" class="cps-button" data-rpg="tab:${k}" aria-pressed="${tab===k}">${icon(ic)}<span>${E(tr(en,th))}</span><small>${String(i+1).padStart(2,'0')}</small></button>`).join('')}<div class="cps-rpg-link-state"><i></i> ${E(tr('CHAT LINKED','เชื่อมต่อแชต'))}<small>${E(actorName==='user'?api.context()?.name1||'USER':actorName)}</small></div></nav><div class="cps-rpg-main-column"><div class="cps-rpg-mobile-nav"><label>${E(tr('SECTION','หมวด'))}<select data-section-picker aria-label="${E(tr('Cyberware section','หมวด Cyberware'))}">${sections.map(([k,en,th])=>`<option value="${k}" ${tab===k?'selected':''}>${E(tr(en,th))}</option>`).join('')}</select></label><span class="cps-state-pill">● ${E(tr('LIVE','เชื่อมต่อ'))}</span></div><div class="cps-rpg-body" tabindex="0" aria-label="${E(sectionTitle(tab))}"></div></div></div>`;
    const area=body.querySelector('.cps-rpg-body');
    if(tab==='status')area.innerHTML=statusMarkup(a,s);
    if(['cyberware','weapons','inventory'].includes(tab)){const items=a.inventory.filter(it=>tab==='inventory'||it.category===tab);area.innerHTML=`${heading(tab==='cyberware'?'RIPPERDOC / LOADOUT':'EQUIPMENT DATABASE',sectionTitle(tab),`${items.length} ${tr('ITEMS','รายการ')}`)}${tab==='cyberware'?`<div class="cps-loadout-overview">${bodyDiagram(a)}<div class="cps-loadout-summary">${meter('CYBERWARE',C.load(a),a.capacity)}${buttons(tr('Manage Capacity / sources','แก้ Capacity / ดูที่มา'),'manage-capacity')}<div class="cps-socket-total"><strong>${a.inventory.filter(it=>it.category==='cyberware'&&it.equipped).length}<small> / ${C.implantGroups.reduce((n,g)=>n+C.slotLimit(a,g.id),0)}</small></strong><span>${E(tr('IMPLANT SOCKETS','ช่องฝังไซเบอร์แวร์'))}</span></div>${note(tr('Select an occupied socket to inspect its implant, or an empty socket to browse compatible equipment.','แตะช่องที่ติดตั้งเพื่อดูอุปกรณ์ หรือช่องว่างเพื่อเลือกอุปกรณ์ที่เข้ากัน'))}</div>${implantSlots(a)}</div>`:''}<div class="cps-rpg-actions">${buttons(tr('Browse catalog','ค้นหาแค็ตตาล็อก'),'catalog')}${buttons(tr('Add custom item','เพิ่มไอเท็มเอง'),'custom-item')}</div><div class="cps-rpg-items">${items.map(it=>itemMarkup(it,s)).join('')||`<div class="cps-rpg-empty">${icon(tab==='inventory'?'item':tab)}<strong>${E(tr('No equipment stored','ยังไม่มีอุปกรณ์'))}</strong>${note(tr('Add the equipment established in your story.','เพิ่มอุปกรณ์ที่มีอยู่ในเนื้อเรื่อง'))}</div>`}</div>`;}
    if(tab==='balance')area.innerHTML=`${buttons(tr('Payment requests','คำขอชำระเงิน'),'payments')}${s.properties.map(x=>`<article class="cps-payment"><small>PROPERTY</small><h3>${E(x.name)}</h3>${note(x.description)}</article>`).join('')}${heading('EURODOLLAR ACCOUNT',sectionTitle(tab))}<div class="cps-account-card"><span>AVAILABLE BALANCE</span><h3><small>€$</small> ${a.balance.toLocaleString()}</h3><footer><span>${E(actorName==='user'?api.context()?.name1||'USER':actorName)}</span><b>LOCAL ACCOUNT</b></footer></div><div class="cps-rpg-actions">${buttons(tr('Transfer','โอนเงิน'),'transfer')}</div>${heading('TRANSACTION LOG',tr('Recent activity','รายการล่าสุด'),String(a.ledger.length))}<div class="cps-rpg-ledger">${a.ledger.slice().reverse().map(e=>`<article class="${e.delta>0?'credit':'debit'}"><div><small>${E(e.delta>0?tr('RECEIVED','รับเข้า'):tr('SENT / ADJUSTED','โอนออก / ปรับยอด'))}</small><p>${E(e.reason)}</p><time>${E(new Date(e.at).toLocaleString(api.settings().language==='th'?'th-TH':'en-GB'))}</time></div><strong>${e.delta>0?'+':''}${e.delta.toLocaleString()}<small>€$</small></strong></article>`).join('')||note(tr('No transactions yet.','ยังไม่มีรายการ'))}</div><details class="cps-rpg-advanced"><summary>${E(tr('Transfer by chat / starting balance','โอนผ่านแชต / ยอดเงินเริ่มต้น'))}</summary>${note('/cp transfer @lucy 500\nโอนเงิน 500 ให้ @lucy')}${buttons(tr('Set starting balance','ตั้งยอดเงินเริ่มต้น'),'setup')}</details>`;
    if(tab==='quickhacks')area.innerHTML=(actorName==='user'?`<nav class="cps-device-deck-tabs" aria-label="Deck type">${buttons(tr('Quickhacks','Quickhacks'),'deck-mode:quickhacks',`aria-pressed="${deckMode==='quickhacks'}"`)}${buttons(tr('Device Hacks','แฮ็กอุปกรณ์'),'deck-mode:devices',`aria-pressed="${deckMode==='devices'}"`)}</nav>`:'')+(actorName==='user'&&deckMode==='devices'?devices.deckMarkup():`${deckMarkup(a)}${heading('OWNED PROGRAMS',tr('Quickhack inventory','คลัง Quickhack'),String(a.inventory.filter(it=>it.category==='quickhack'&&it.quantity>0).length))}<div class="cps-rpg-items">${a.inventory.filter(it=>it.category==='quickhack'&&it.quantity>0).map(it=>itemMarkup(it,s)).join('')}</div>`);
    if(tab==='skills')area.innerHTML=`${buttons(tr('Manage Quickhack Deck','จัดการเด็ค Quickhack'),'tab:quickhacks')}${s.hackingRequest?.status==='pending'?buttons(tr('Pending access point','จุดเชื่อมต่อที่รอ'),'hack-request'):''}${heading('NEURAL TOOLKIT',sectionTitle(tab),`${a.skills.length} ${tr('SKILLS','ทักษะ')}`)}<div class="cps-breach-launcher">${icon('quickhack')}<div><small>ACCESS POINT INTERFACE</small><h3>Breach Protocol</h3></div>${buttons(tr('Training','ฝึกแฮ็ก'),'practice')}${s.puzzle&&['ready','running'].includes(s.puzzle.status)?buttons(tr('Resume','เปิดต่อ'),'resume'):''}</div><div class="cps-rpg-actions">${buttons(tr('Add skill','เพิ่มสกิล'),'add-skill')}</div><div class="cps-ability-grid">${a.skills.map(sk=>skillMarkup(sk,s)).join('')||note(tr('Abilities used in the story appear here.','ทักษะที่ใช้ในเนื้อเรื่องจะแสดงที่นี่'))}</div>`;
    if(tab==='quests')area.innerHTML=`${heading('JOURNAL / CONTRACTS',sectionTitle(tab),`${s.quests.filter(q=>['active','ready'].includes(q.status)).length} ACTIVE`)}<div class="cps-rpg-actions">${buttons(tr('Add mission','เพิ่มภารกิจ'),'add-quest')}</div>${s.questOffers.filter(o=>o.status!=='accepted').map(o=>questOfferCard(o)).join('')}${s.quests.map(q=>`<article class="cps-quest-card ${E(q.status)}"><header><span>${E(q.status.toUpperCase())}</span><small>MISSION FILE</small></header><h3>${E(q.title)}</h3>${note(q.description)}${questBody(q)}<div class="cps-quest-objective"><i aria-hidden="true"></i><div><small>${E(tr('OBJECTIVE','เป้าหมาย'))}</small><p>${E(q.objective||tr('Awaiting briefing','รอข้อมูลภารกิจ'))}</p></div></div><div class="cps-rpg-actions">${buttons(tr('Share briefing','ส่งข้อมูลภารกิจ'),`share-quest:${q.id}`)}${q.status==='active'&&!q.objectives?.length?buttons(tr('Task done / prepare hand-in','ทำเป้าหมายแล้ว / เตรียมส่งงาน'),`ready-quest:${q.id}`):''}${q.status==='ready'&&!q.paid?buttons(tr('Turn in / claim reward','ส่งงาน / รับรางวัล'),`turn-in:${q.id}`):''}${!q.paid?buttons(q.status==='failed'?tr('Reopen mission','เปิดภารกิจใหม่'):tr('Mark failed','ระบุว่าล้มเหลว'),`quest:${q.id}`):''}</div></article>`).join('')||(!s.questOffers.length?note(tr('No mission data received.','ยังไม่ได้รับข้อมูลภารกิจ')):'')}`;
    if(tab==='map')renderMap(area);
    if(tab==='relic')area.innerHTML=relicMarkup(a)+buttons(tr('AI / Blackwall channel','ช่องสนทนา AI / Blackwall'),'tab:ai');
    if(tab==='property'||tab==='vehicles')area.innerHTML=assetsMarkup(tab);
    if(tab==='ai')area.innerHTML=heading('NEURAL COMMUNICATIONS','AI / BLACKWALL')+note(tr('Private neural conversations. Main-chat AI speech uses its own decrypted header.','ช่องสนทนาประสาทส่วนตัว ข้อความ AI ในแชตหลักมี Header และเอฟเฟกต์ถอดรหัส'))+buttons('BLACKWALL','ai-open:Blackwall',!s.player.blackwall.unlocked?'disabled':'')+buttons(tr('Connect AI','เชื่อมต่อ AI'),'ai-custom');
    if(tab==='settings')area.innerHTML=`<label class="cps-bd-toggle"><input type="checkbox" role="switch" data-bd-switch ${s.bd.enabled?'checked':''}>${E(tr('Braindance floating control','ปุ่มลอย Braindance'))}</label>${buttons('Braindance','braindance')}${heading('SYSTEM PREFERENCES',sectionTitle(tab))}<form data-rpg-settings class="cps-rpg-preferences"><label class="cps-preference-switch"><span>${tr('Immersion notifications','แจ้งเตือนบรรยากาศ')}</span><input name="notifications" type="checkbox" ${s.settings.notifications?'checked':''} role="switch"></label><label><span>${tr('Dismiss after (seconds)','เวลาหาย (วินาที)')}</span><input name="noticeSeconds" type="number" min="2" max="60" value="${s.settings.noticeSeconds}" required></label><label><span>${tr('Neural load multiplier (0 disables)','ตัวคูณภาระระบบประสาท (0 = ปิด)')}</span><input name="riskScale" type="number" min="0" max="3" step="0.1" value="${s.settings.riskScale}" required></label><button class="cps-button primary" type="submit">${tr('Save preferences','บันทึกการตั้งค่า')}</button></form>${note(tr('Saved for this chat. Display colors and animations follow the main extension settings.','บันทึกแยกตามแชต สีและแอนิเมชันใช้ค่าจากการตั้งค่า extension'))}`;
    if(['status','cyberware'].includes(tab)&&actorName==='user')area.insertAdjacentHTML('afterbegin',`<div class="cps-medical-launch">${buttons(tr('Cyberpsycho / Medical Link','Cyberpsycho / ระบบการแพทย์'),'medical')}<span>${E(C.medical.assess(s.player,s.turn,s.settings.riskScale).level.toUpperCase())}</span></div>`);
    body.querySelector('[data-bd-switch]')?.addEventListener('change',e=>{s.bd.enabled=e.target.checked;save();bdButton();});
    if(tab==='quickhacks'&&actorName==='user'&&deckMode==='devices')devices.bindDeck(area);
    body.querySelectorAll('[data-deck-slot]').forEach(select=>select.onchange=()=>guard(()=>{C.setQuickhackSlot(a,Number(select.dataset.deckSlot),select.value||null);save();render();}));
    body.querySelectorAll('[data-rpg]').forEach(b=>b.onclick=()=>guard(()=>action(b.dataset.rpg)));
    body.querySelectorAll('[data-quest-offer] [data-offer-action]').forEach(b=>b.onclick=()=>guard(()=>decideQuestOffer(b.closest('[data-quest-offer]').dataset.questOffer,b.dataset.offerAction)));
    body.querySelector('[data-section-picker]').onchange=e=>{if(e.target.value==='support'){e.target.value=tab;support.open();return;}if(e.target.value==='mail'){e.target.value=tab;mail.open();return;}navigateSection(e.target.value);};
    body.querySelector('[data-rpg-settings]')?.addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;s.settings={...s.settings,notifications:f.elements.notifications.checked,noticeSeconds:C.cap(f.elements.noticeSeconds.value,2,60),riskScale:C.cap(f.elements.riskScale.value,0,3)};save();api.toast(tr('Saved','บันทึกแล้ว'));});
    for(const draft of drafts){const el=[...body.querySelectorAll('[name]')].find(x=>x.name===draft.name);if(el){el.value=draft.value;el.checked=draft.checked;}}
    if(focused)[...body.querySelectorAll('[name]')].find(x=>x.name===focused)?.focus({preventScroll:true});
    area.scrollTop=scroll;
    if(!sameTab){area.classList.add('cps-page-enter');area.style.setProperty('--cps-page-direction','1');}
  }
  function form(title,fields,submit){
    const owner=safeOwner();
    const d=dialog(title,`<form class="cps-rpg-form">${fields.map(([name,label,value='',type='text',extra=''])=>`<label>${E(label)}${type==='textarea'?`<textarea name="${name}" ${extra}>${E(value)}</textarea>`:type==='select'?`<select name="${name}">${value}</select>`:`<input name="${name}" type="${type}" value="${E(value)}" ${extra}>`}</label>`).join('')}<button class="cps-button primary" type="submit">${tr('Save / Send','บันทึก / ส่ง')}</button><p role="alert" data-error></p></form>`);
    d.querySelector('form').onsubmit=e=>{e.preventDefault();try{if(owner!==safeOwner()||!d.isConnected)throw Error('Chat changed; reopen this form.');submit(Object.fromEntries(new FormData(e.currentTarget)));api.removeUiDialog(d);save();render();}catch(err){d.querySelector('[data-error]').textContent=err.message;}};return d;
  }
